"use client";

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useMemo,
  type ReactNode,
} from "react";

import { onIdTokenChanged } from "firebase/auth";
import axios, { AxiosInstance } from "axios";
import { createApiClient } from "@/src/lib/api";

import {
  getAuth,
  signInWithEmailAndPassword,
  type User as FirebaseUser,
} from "firebase/auth";
import { getFirebaseAuth } from "@/src/lib/firebase";

import type { LoginResponse } from "@/src/types/auth";

export interface LaravelUser {
  id: number;
  name: string;
  email: string;
  user_image?: string | null;
}

export interface AuthContextType {
  user: LaravelUser | null;
  firebaseUser: FirebaseUser | null;

  apiClient: AxiosInstance | null;
  token: string | null;

  isAuthenticated: boolean;
  isLoading: boolean;

  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | null>(null);

const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL!;

// ====================================================================
// Provider
// ====================================================================
export function AuthProvider({ children }: { children: ReactNode }) {
  const auth = getFirebaseAuth();

  const [firebaseUser, setFirebaseUser] = useState<FirebaseUser | null>(null);
  const [user, setUser] = useState<LaravelUser | null>(null);

  const [token, setToken] = useState<string | null>(null);
  const [apiClient, setApiClient] = useState<AxiosInstance | null>(null);

  const [isLoading, setIsLoading] = useState(true);

  // ====================================================================
  // 初期ログイン確定処理（onAuthStateChanged）
  // ====================================================================
  useEffect(() => {
    console.log("[AuthProvider] START onAuthStateChanged");

    const unsub = auth.onAuthStateChanged(async (u) => {
      console.log("[AuthProvider] Firebase user =", u);

      // --- ★★ 修正ポイント：初回 null を無視する ★★ ---
      if (!u) {
        console.log("[AuthProvider] Firebase user = null → 初回なので無視");
        setIsLoading(false);
        return;
      }

      // Firebase ユーザーをセット
      setFirebaseUser(u);

      const idToken = await u.getIdToken();

      try {
        const { data } = await axios.post<LoginResponse>(
          `${API_BASE_URL}/api/login_or_register`,
          { id_token: idToken },
        );

        const newToken = data.token;
        setToken(newToken);

        const client = createApiClient(newToken);
        setApiClient(client);

        const me = await client.get("/api/user");
        setUser(me.data.user);
      } catch (err) {
        console.error("[AuthProvider] Token Login failed", err);
      }

      setIsLoading(false);
    });

    return () => unsub();
  }, [auth]);

  // ====================================================================
  // Token 自動更新（onIdTokenChanged）
  // ====================================================================
  useEffect(() => {
    const unsub = onIdTokenChanged(auth, async (u) => {
      if (!u) {
        console.log("[TokenRefresh] Firebase user null (ignore)");
        return;
      }

      const newFirebaseToken = await u.getIdToken();
      console.log("[TokenRefresh] New Firebase ID Token issued");

      // Laravel へ再ログイン（Token 更新）
      const response = await axios.post<LoginResponse>(
        `${API_BASE_URL}/api/login_or_register`,
        { id_token: newFirebaseToken },
      );

      const newToken = response.data.token;
      console.log(
        "[TokenRefresh] New Laravel API Token =",
        newToken.substring(0, 10),
      );

      setToken(newToken);
      setApiClient(createApiClient(newToken));
    });

    return () => unsub();
  }, [auth]);

  // ====================================================================
  // login（メールログイン）
  // ====================================================================
  const login = useCallback(
    async (email: string, password: string) => {
      setIsLoading(true);

      try {
        const cred = await signInWithEmailAndPassword(auth, email, password);
        const idToken = await cred.user.getIdToken();

        const { data } = await axios.post<LoginResponse>(
          `${API_BASE_URL}/api/login_or_register`,
          { id_token: idToken },
        );

        const newToken = data.token;

        setFirebaseUser(cred.user);
        setToken(newToken);

        const client = createApiClient(newToken);
        setApiClient(client);

        const me = await client.get("/api/user");
        setUser(me.data.user);
      } finally {
        setIsLoading(false);
      }
    },
    [auth],
  );

  // ====================================================================
  // logout
  // ====================================================================
  const logout = useCallback(async () => {
    await auth.signOut();
    setUser(null);
    setToken(null);
    setApiClient(null);
    setFirebaseUser(null);
  }, [auth]);

  // ====================================================================
  // ログイン判定
  // ====================================================================
  const isAuthenticated = useMemo(() => {
    return !!user && !!token;
  }, [user, token]);

  const value: AuthContextType = {
    user,
    firebaseUser,
    apiClient,
    token,
    isAuthenticated,
    isLoading,
    login,
    logout,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

// ====================================================================
// Hooks
// ====================================================================
export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside <AuthProvider>");
  return ctx;
}

export function useApiClient() {
  const { apiClient } = useAuth();
  if (!apiClient) throw new Error("API client not ready");
  return apiClient;
}
